package levels_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"qinqin/internal/dbtest"
	"qinqin/internal/levels"
	"qinqin/internal/pack"
)

// bundledPacks is the committed default seed root, relative to this
// package's test working directory.
const bundledPacks = "../../../plugins/data"

// TestBundledLevelPacks: the level packs generated by
// scripts/prepare-level-packs.mjs (jlpt-kanji),
// scripts/prepare-jlpt-words.mjs (jlpt-words) and
// scripts/prepare-hsk-syllabus.mjs (hsk-words, hsk-chars) load as valid levels packs
// with their scheme names, units and levels in easy-to-hard order, carry
// a licence statement and attribution (with the licence file, or for the
// HSK syllabus, which grants no reuse licence, the CTI Legal Notice terms
// in ATTRIBUTION.md), carry the valid manifest notice the Sources page
// shows (the approximation caveat, the CTI terms), and import cleanly — into an empty lexicon every form
// is skipped and reported, none fails the import.
func TestBundledLevelPacks(t *testing.T) {
	jlpt := []string{"N5", "N4", "N3", "N2", "N1"}
	jlptApprox := []string{"≈ N5", "≈ N4", "≈ N3", "≈ N2", "≈ N1"}
	hsk := []string{"HSK 1", "HSK 2", "HSK 3", "HSK 4", "HSK 5", "HSK 6", "HSK 7–9"}
	cases := []struct {
		id, name, language, unit string
		levels                   []string
		total                    int      // forms over all levels; 0 = not pinned
		license                  string   // the manifest's licence
		files                    []string // files that must sit beside the manifest
		notice                   []string // substrings the manifest notice must hold
	}{
		// kanjiapi.dev's 2,211 kanji plus the 176 it omits that the
		// KANJIDIC2 gap fill places (scripts/prepare-level-packs.mjs).
		{"jlpt-kanji", "JLPT kanji (approximate)", "ja", "character", jlpt, 2387,
			"MIT AND CC BY-SA 4.0", []string{"ATTRIBUTION.md", "LICENSE", "LICENSE-KANJIDIC2"},
			[]string{"The JLPT kanji levels are approximate", "(https://github.com/onlyskin/kanjiapi.dev)", "KANJIDIC2"}},
		// The estimate: Jiten ranks cut at the commonly cited cumulative
		// sizes (800 … 10,000), less one {form, reading} two entries share.
		{"jlpt-words", "JLPT words (approximate)", "ja", "word", jlptApprox, 9999,
			"CC BY-SA 4.0", []string{"ATTRIBUTION.md", "LICENSE", "LICENSE-kanjiapi.dev", "UNMATCHED.tsv"},
			[]string{"an estimate, not an official list", "since 2010", "(https://jiten.moe/frequency-dictionaries)", "JMdict"}},
		// 11,000 syllabus rows less 41 homographs with the reading of an
		// easier one (本1, 本2 běn).
		{"hsk-words", "HSK 3.0 (words)", "zh", "word", hsk, 10959,
			"See CTI Legal Notice; no reuse licence granted", []string{"ATTRIBUTION.md"},
			[]string{"official word list (HSK 词汇大纲)", "[Legal Notice](https://www.chinesetest.cn/legal-notice)", "has not been verified"}},
		// The syllabus's 认读字 lists: 246, 125, 284, 441, 431, 413, 1,148.
		{"hsk-chars", "HSK 3.0 (characters)", "zh", "character", hsk, 3088,
			"See CTI Legal Notice; no reuse licence granted", []string{"ATTRIBUTION.md"},
			[]string{"official character list (HSK 汉字大纲", "[Legal Notice](https://www.chinesetest.cn/legal-notice)", "has not been verified"}},
	}
	for _, c := range cases {
		t.Run(c.id, func(t *testing.T) {
			dir := filepath.Join(bundledPacks, c.id)
			p, err := pack.LoadPack(dir)
			if err != nil {
				t.Fatalf("LoadPack: %v", err)
			}
			m := p.Manifest
			if m.ID != c.id || m.Name != c.name || m.Language != c.language || m.Type != pack.TypeLevels {
				t.Errorf("manifest = %+v, want id %s, name %q, language %s, type levels", m, c.id, c.name, c.language)
			}
			if m.License != c.license || m.Attribution == "" {
				t.Errorf("license %q, attribution %q; want %q with an attribution", m.License, m.Attribution, c.license)
			}
			if m.Notice == "" {
				t.Error("manifest has no notice")
			}
			if err := pack.ValidateNotice(m.Notice); err != nil {
				t.Errorf("notice: %v", err)
			}
			for _, want := range c.notice {
				if !strings.Contains(m.Notice, want) {
					t.Errorf("notice lacks %q", want)
				}
			}
			for _, f := range c.files {
				if _, err := os.Stat(filepath.Join(dir, f)); err != nil {
					t.Errorf("%s: %v", f, err)
				}
			}

			raw, err := os.ReadFile(filepath.Join(dir, "levels.json"))
			if err != nil {
				t.Fatal(err)
			}
			var data struct {
				Unit   string `json:"unit"`
				Levels []struct {
					Name    string            `json:"name"`
					Entries []json.RawMessage `json:"entries"` // a form, or {"form", "reading"}
				} `json:"levels"`
			}
			if err := json.Unmarshal(raw, &data); err != nil {
				t.Fatal(err)
			}
			if data.Unit != c.unit {
				t.Errorf("unit = %q, want %q", data.Unit, c.unit)
			}
			var names []string
			total := 0
			distinct := map[string]bool{}
			for _, lv := range data.Levels {
				names = append(names, lv.Name)
				if len(lv.Entries) == 0 {
					t.Errorf("level %s is empty", lv.Name)
				}
				total += len(lv.Entries)
				for _, e := range lv.Entries {
					var form string
					if json.Unmarshal(e, &form) != nil {
						var obj struct{ Form string }
						if err := json.Unmarshal(e, &obj); err != nil {
							t.Fatalf("entry %s: %v", e, err)
						}
						form = obj.Form
					}
					distinct[strings.TrimSpace(form)] = true
				}
			}
			if !slices.Equal(names, c.levels) {
				t.Errorf("levels = %q, want %q", names, c.levels)
			}
			if c.total != 0 && total != c.total {
				t.Errorf("%d forms, want %d", total, c.total)
			}

			res, err := levels.Import(context.Background(), dbtest.Open(t), p)
			if err != nil {
				t.Fatalf("Import into an empty lexicon: %v", err)
			}
			if res.Levels != len(c.levels) || res.Members != 0 || len(res.Skipped) != len(distinct) {
				t.Errorf("Import = %d levels, %d members, %d skipped; want %d, 0, %d",
					res.Levels, res.Members, len(res.Skipped), len(c.levels), len(distinct))
			}
		})
	}
}
